      models: same(const <String, double>{'t': 2.2}),
      interpret: pick('ca', 'Both countries gain when the terms of trade lie', 'between their opportunity costs', const <String>['above both opportunity costs', 'below both opportunity costs'], explain: ''),
    ),
    DesignProblem(
      key: 'ppp',
