      outputs: const <SimOutput>[SimOutput('I', 'PPP rate', '5.5/p', unit: '\$ per £', decimals: 3), SimOutput('V', 'Over(+)/under(−) valuation of £', '(r/I - 1)*100', unit: '%', decimals: 2), SimOutput('Z', 'Size of misvaluation', 'abs(V)', unit: '%', decimals: 2)],
